    col += streaksAt(sl, rel, 6.0 * F, 64.0 * uDpr, 0.12, 1.0, 0.65);
    if (uCheap < 0.5) col += streaksAt(sl, rel, 2.5 * F, 90.0 * uDpr, 0.18, 21.0, 0.45) * 0.8;
